592	  String _nextLocalId() => 'local-${_localIdCounter++}';
593	
594	  /// spec-6-3 — [_connectivityWatcher]'s own listener: [isOnline] `true`
595	  /// means the device currently has connectivity. Always updates
596	  /// [_isOffline] (even outside [ChatReady] — see [_isOffline]'s own doc),
597	  /// but only *emits* when already [ChatReady] and the value actually
598	  /// changed, so an unrelated repeated emission of the same status (e.g.
599	  /// a plugin re-announcing "still online") never triggers a spurious
600	  /// rebuild.
601	  void _handleConnectivityChange(bool isOnline) {
602	    _isOffline = !isOnline;
603	    if (isClosed) {
604	      return;
605	    }
606	    final current = state;
607	    if (current is ChatReady && current.isOffline != _isOffline) {
608	      emit(current.copyWith(isOffline: _isOffline));
609	    }
610	  }
