26	/// A controllable fake — this suite drives `sendMessage`'s own SSE-shaped
27	/// stream event by event (rather than mocktail-stubbing a fixed `Stream`),
28	/// so each test can assert the cubit's state *between* events (e.g. right
29	/// after one `token` but before `done`).
30	class _FakeChatRepository implements ChatRepository {
31	  Either<Failure, List<ChatSession>> listSessionsResult = right([_session]);
32	  Either<Failure, ChatSession> createSessionResult = right(_session);
33	  Either<Failure, List<ChatMessage>> listMessagesResult = right(const []);
34	
35	  StreamController<Either<Failure, ChatStreamEvent>>? lastSendController;
36	  final List<({String sessionId, String content})> sendMessageCalls = [];
37	
38	  StreamController<Either<Failure, ChatStreamEvent>>? lastRetryController;
39	  final List<({String sessionId, String userMessageId})> retryMessageCalls = [];
40	
41	  @override
42	  Future<Either<Failure, List<ChatSession>>> listSessions() async =>
43	      listSessionsResult;
44	
45	  @override
46	  Future<Either<Failure, ChatSession>> createSession() async =>
47	      createSessionResult;
48	
49	  @override
50	  Future<Either<Failure, List<ChatMessage>>> listMessages(
51	    String sessionId,
52	  ) async => listMessagesResult;
53	
54	  @override
55	  Stream<Either<Failure, ChatStreamEvent>> sendMessage(
56	    String sessionId,
57	    String content,
58	  ) {
59	    sendMessageCalls.add((sessionId: sessionId, content: content));
60	    final controller = StreamController<Either<Failure, ChatStreamEvent>>();
61	    lastSendController = controller;
62	    return controller.stream;
63	  }
64	
65	  @override
66	  Stream<Either<Failure, ChatStreamEvent>> retryMessage(
67	    String sessionId,
68	    String userMessageId,
69	  ) {
70	    retryMessageCalls.add(
71	      (sessionId: sessionId, userMessageId: userMessageId),
72	    );
73	    final controller = StreamController<Either<Failure, ChatStreamEvent>>();
74	    lastRetryController = controller;
75	    return controller.stream;
76	  }
77	}
