41	/// A controllable fake — lets each test drive bootstrap success/failure
42	/// and inspect [sendMessageCalls] without a mocking framework, same
43	/// pattern `chat_cubit_test.dart`'s own fake already uses.
44	class _FakeChatRepository implements ChatRepository {
45	  Either<Failure, List<ChatSession>> listSessionsResult = right([_session]);
46	  Either<Failure, List<ChatMessage>> listMessagesResult = right(const []);
47	  Either<Failure, ChatSession> createSessionResult = right(_session);
48	  final List<String> sendMessageCalls = [];
49	  StreamController<Either<Failure, ChatStreamEvent>>? lastSendController;
50	  final List<String> retryMessageCalls = [];
51	  StreamController<Either<Failure, ChatStreamEvent>>? lastRetryController;
52	
53	  @override
54	  Future<Either<Failure, List<ChatSession>>> listSessions() async =>
55	      listSessionsResult;
56	
57	  @override
58	  Future<Either<Failure, ChatSession>> createSession() async =>
59	      createSessionResult;
60	
61	  @override
62	  Future<Either<Failure, List<ChatMessage>>> listMessages(
63	    String sessionId,
64	  ) async => listMessagesResult;
65	
66	  @override
67	  Stream<Either<Failure, ChatStreamEvent>> sendMessage(
68	    String sessionId,
69	    String content,
70	  ) {
71	    sendMessageCalls.add(content);
72	    final controller = StreamController<Either<Failure, ChatStreamEvent>>();
73	    lastSendController = controller;
74	    return controller.stream;
75	  }
76	
77	  @override
78	  Stream<Either<Failure, ChatStreamEvent>> retryMessage(
79	    String sessionId,
80	    String userMessageId,
81	  ) {
82	    retryMessageCalls.add(userMessageId);
83	    final controller = StreamController<Either<Failure, ChatStreamEvent>>();
84	    lastRetryController = controller;
85	    return controller.stream;
86	  }
87	}
