/// AD-13 — the never-throws wrapper RF08 and RF10 both need for a side
/// effect that must never block or crash its caller, even on failure.
///
/// RF10 (spec-6-4, this story) is the first real consumer, per the
/// architecture spine; RF08 (spec-6-5) reuses it fire-and-forget
/// (unawaited). RF10 awaits it directly.
typedef IsolatedSideEffect<T> = Future<Either<Failure, T>> Function(
  Future<T> Function() action,
);

/// [action] resolving normally passes its value through as `Right`;
/// [action] throwing — synchronously or asynchronously — is caught and
/// mapped to `Left(Failure.malformedResponse(...))` rather than ever
/// propagating to the caller (RNF09), mirroring
/// `EntriesRepositoryImpl`'s own catch-to-`malformedResponse` convention
/// for a local (non-backend) failure.
Future<Either<Failure, T>> isolatedSideEffect<T>(
  Future<T> Function() action,
) async {
  try {
    return right(await action());
  } catch (error) {
    return left(Failure.malformedResponse(message: error.toString()));
  }
}

