302	  group('spec-6-3 — "Novo Chat" disables while ChatReady.isOffline', () {
303	    // Deliberately builds its own `ChatCubit`/`FakeConnectivityWatcher`
304	    // pair inside each test body below, rather than reusing the shared
305	    // `cubit`/`fakeConnectivityWatcher` the outer `setUp()` constructs —
306	    // `ChatCubit`'s constructor subscribes to the watcher's stream
307	    // immediately, and a subscription created inside an *async* `setUp()`
308	    // callback is registered in a different zone than the one
309	    // `tester.pumpAndSettle()` drains for a `testWidgets` body (a known
310	    // `flutter_test` gotcha: `setUp()`'s own async work runs outside
311	    // `TestWidgetsFlutterBinding`'s per-test zone), so a later
312	    // `watcher.emit(...)` call's effect on the widget tree would never be
313	    // observed by `pumpAndSettle()` within the test body. Constructing
314	    // both inside the test body itself keeps everything in the one zone
315	    // `pumpAndSettle()` actually watches.
316	    Future<({ChatCubit cubit, FakeConnectivityWatcher watcher})> boot(
317	      WidgetTester tester,
318	    ) async {
319	      final repository = _FakeChatRepository();
320	      final watcher = FakeConnectivityWatcher();
321	      final localCubit = ChatCubit(repository, watcher);
322	      await localCubit.init();
323	      addTearDown(localCubit.close);
324	      addTearDown(watcher.close);
