/// spec-6-4 (RF10) — the save-to-journal bookmark affordance:
/// `EntriesRepository.create(..., source: EntrySource.chat,
/// chatMessageId: ...)` through `isolatedSideEffect`, awaited before the
/// tapped bubble's own [ChatUiMessage.bookmarkState] updates.
///
/// A no-op (Boundaries/I/O matrix) while [state] isn't [ChatReady], when
/// [messageId] doesn't match any loaded message, when that message's
/// [ChatUiMessage.role] isn't [ChatMessageRole.user] (never shown/wired
/// on an AI bubble to begin with, but guarded here too — same
/// defensive shape [retryMessage]'s own role check uses), when its
/// [ChatUiMessage.serverId] is still `null` (mirrors [retryMessage]'s
/// "never calling with no serverId" guard — the backend has nothing to
/// key `chatMessageId` off yet), or when its [BookmarkState] is already
/// [BookmarkSaved]/[BookmarkSaving] (Boundaries: "tapping an already-
/// saved message is a no-op"; the re-entrancy guard for "second tap
/// while saving" reuses this exact same state check, scoped to this one
/// message — mirrors [_isSending]'s own role for [sendMessage]/
/// [retryMessage], just read off the message itself rather than a
/// cubit-wide field, since two different messages' own bookmark saves
/// are never mutually exclusive the way sends/retries are).
///
/// [EntriesRepository.create]'s own `Left`/thrown-exception cases both
/// resolve to [BookmarkState.error] here — `isolatedSideEffect` already
/// collapses "the call itself threw" into a `Left(Failure.
/// malformedResponse(...))` (RNF09), so this method only ever matches on
/// the `Either` it hands back, same `for...if...else` message-rebuild
/// shape [retryMessage]'s own `_applyStreamEvent` call sites use.
Future<void> bookmarkMessage(String messageId) async {
  final current = state;
  if (current is! ChatReady) {
    return;
  }
  final index = current.messages.indexWhere(
    (message) => message.id == messageId,
  );
  if (index == -1) {
    return;
  }
  final message = current.messages[index];
  if (message.role != ChatMessageRole.user) {
    return;
  }
  final serverId = message.serverId;
  if (serverId == null) {
    return;
  }
  if (message.bookmarkState is BookmarkSaved ||
      message.bookmarkState is BookmarkSaving) {
    return;
  }

  emit(
    current.copyWith(
      messages: [
        for (final existing in current.messages)
          if (existing.id == messageId)
            existing.copyWith(bookmarkState: const BookmarkState.saving())
          else
            existing,
      ],
    ),
  );

  final result = await isolatedSideEffect(
    () => _entriesRepository.create(
      content: message.content,
      source: EntrySource.chat,
      chatMessageId: serverId,
    ),
  );

  if (isClosed) {
    return;
  }
  final latest = state;
  if (latest is! ChatReady) {
    return;
  }
  emit(
    latest.copyWith(
      messages: [
        for (final existing in latest.messages)
          if (existing.id == messageId)
            existing.copyWith(
              bookmarkState: result.match(
                (failure) => BookmarkState.error(failure),
                (_) => const BookmarkState.saved(),
              ),
            )
          else
            existing,
      ],
    ),
  );
}

