/// dependency: [createResult] drives `bookmarkMessage()`'s own `Right`/
/// `Left` branch per test, and [createCalls] records every `content`/
/// `source`/`chatMessageId` triple passed through, so a test can assert
/// `create()` was called exactly once (never twice for the same message —
/// I/O matrix: "Already saved"/"Second tap while saving").
class _FakeEntriesRepository implements EntriesRepository {
  Either<Failure, Entry> createResult = right(
    const Entry(
      id: 'entry-1',
      content: 'conteúdo',
      source: EntrySource.chat,
      chatMessageId: 'srv-1',
      occurredAt: '2026-01-01T00:00:00Z',
      serverRevision: 1,
      createdAt: '2026-01-01T00:00:00Z',
      updatedAt: '2026-01-01T00:00:00Z',
    ),
  );

  final List<({String content, EntrySource source, String? chatMessageId})>
  createCalls = [];

  @override
  Future<Either<Failure, Entry>> create({
    required String content,
    required EntrySource source,
    int? mediaDurationSeconds,
    String? chatMessageId,
  }) async {
    createCalls.add((
      content: content,
      source: source,
      chatMessageId: chatMessageId,
    ));
    return createResult;
  }

  @override
  Future<Either<Failure, EntriesPage>> list({
    String? cursor,
    int limit = 20,
    EntrySource? source,
    DateTime? dateFrom,
    DateTime? dateTo,
  }) async => throw UnimplementedError('not expected to be called');

  @override
  Future<Either<Failure, Entry>> getById(String id) async =>
      throw UnimplementedError('not expected to be called');

  @override
  Future<Either<Failure, List<Entry>>> search(
    String query, {
    EntrySource? source,
    DateTime? dateFrom,
    DateTime? dateTo,
  }) async => throw UnimplementedError('not expected to be called');
}

