/// When non-null, `create()` resolves from this completer instead of
/// returning [createResult] immediately — lets a test freeze the call
/// mid-flight to assert the `saving` state is actually visible before
/// it resolves.
Completer<Either<Failure, Entry>>? pendingCompleter;

/// I/O matrix "Side-effect throws" — when non-null, `create()` throws
/// this instead of returning anything, exercising
/// `isolatedSideEffect`'s own catch-to-`malformedResponse` mapping from
/// inside `bookmarkMessage()` itself, not just `isolated_side_effect_
/// test.dart`'s own isolated unit coverage.
Object? throwOnCreate;

@override
Future<Either<Failure, Entry>> create({
  required String content,
  required EntrySource source,
  int? mediaDurationSeconds,
  String? chatMessageId,
}) async {
  createCalls.add((
    content: content,
    source: source,
    chatMessageId: chatMessageId,
  ));
  final toThrow = throwOnCreate;
  if (toThrow != null) {
    throw toThrow;
  }
  final completer = pendingCompleter;
  if (completer != null) {
    return completer.future;
  }
  return createResult;
}

