          ).first,
        );
        expect(semantics.flagsCollection.isButton, isTrue);

        final constrainedBoxes = tester.widgetList<ConstrainedBox>(
          find.ancestor(
            of: find.byIcon(Icons.bookmark_border),
            matching: find.byType(ConstrainedBox),
